// src/components/OutputDisplay.jsx

import React from 'react';
import {chordDiagrams} from '../data/vocabulary';
/* import './OutputDisplay.css'; */ // Стили для схем аккордов

function renderChordDiagram(diagramsArray, chordName) {
   if (!diagramsArray || diagramsArray.length === 0) {
     return <p>Схемы для {chordName} не найдены</p>;
   }
   
   return (
     <div key={chordName} className="chord-diagram mb-6">
       <h3 className="chord-name mb-2">{chordName}</h3>
       <div className="chord-diagram-container">
         {diagramsArray.map((diagram, idx) => (
           <div key={idx} className="chord-string flex items-center mb-1">
             {[...diagram].map((char, i) => (
               <div key={i} className={`chord-fret flex items-center justify-center w-[22px] h-[24px] mr-[2px] border border-[#555] rounded`}>
                 {char === '-' ? '' : char}
                 {char === 'x' && <span style={{ color: 'red' }}>x</span>}
               </div>
             ))}
           </div>
         ))}
       </div>
     </div>
   );
 }
 
 function OutputDisplay({ sequence }) {
   if (!sequence || sequence.length === 0) {
     return null; // Ничего не показываем до генерации
   }
   
   const uniqueChordsArray = [...new Set(sequence)].sort();
   
   return (
     <>
       {/* Блок с аккордами */}
       <div style={{ backgroundColor: '#3a3a3a', padding: '8px', borderRadius: '4px', marginBottom: '1rem' }}>
         {sequence.map((chord, idx) => (
           <span key={idx} style={{ marginRight: '.5rem' }}>
             {chord}
           </span>
         ))}
       </div>
       
       {/* Блок со схемами */}
       <div>
         {uniqueChordsArray.map(chordName => (
           renderChordDiagram(chordDiagrams[chordName], chordName)
         ))}
       </div>
     </>
   );
 }
 
 export default OutputDisplay;
